import { Direction, Timeframe } from './candle';

/**
 * Trading signal generated by a pattern
 */
export interface Signal {
  // Identity
  patternId: string;
  patternName: string;
  
  // Instrument
  symbol: string;
  direction: Direction;
  timeframe: Timeframe;
  timestamp: number;
  
  // Price levels
  entryPrice: number;
  stopLoss: number;
  target: number;
  
  // Metadata
  confidence: number;              // 0-1 scale
  confluenceFactors: string[];     // e.g., ['fib_618', 'sr_zone', 'trendline']
  invalidationPrice: number;       // Price where pattern is invalid
  
  // Risk
  riskRewardRatio: number;
  suggestedRiskPercent: number;
}

/**
 * Calculate risk-reward ratio from signal
 */
export function calculateRiskReward(signal: Signal): number {
  const risk = Math.abs(signal.entryPrice - signal.stopLoss);
  const reward = Math.abs(signal.target - signal.entryPrice);
  return risk > 0 ? reward / risk : 0;
}

/**
 * Validate signal has reasonable values
 */
export function isValidSignal(signal: Signal): boolean {
  // Entry must be between SL and TP
  if (signal.direction === 'LONG') {
    return signal.stopLoss < signal.entryPrice && signal.entryPrice < signal.target;
  } else {
    return signal.stopLoss > signal.entryPrice && signal.entryPrice > signal.target;
  }
}

